"use client";

import { ChevronDown, ChevronUp, Terminal, Trash2 } from "lucide-react";
import { useEffect, useRef } from "react";
import { Button } from "@/components/ui/button";
import type { ConsoleMessage } from "@/lib/sandbox/types";
import { formatTimestamp, sandboxPanelClassName } from "@/lib/sandbox/utils";
import { cn } from "@/lib/utils";
import { SandboxPanelHeader } from "./panel-chrome";

interface ConsolePanelProps {
  messages: ConsoleMessage[];
  onClear?: () => void;
  collapsed?: boolean;
  onCollapsedChange?: (collapsed: boolean) => void;
  className?: string;
}

const levelTone: Record<ConsoleMessage["level"], string> = {
  log: "text-muted-foreground",
  info: "text-sky-400/90",
  warn: "text-amber-400/90",
  error: "text-red-400/90",
};

export function ConsolePanel({
  messages,
  onClear,
  collapsed = false,
  onCollapsedChange,
  className,
}: ConsolePanelProps) {
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const prevMessageCountRef = useRef<number | null>(null);

  useEffect(() => {
    if (collapsed) {
      return;
    }

    const messageCount = messages.length;

    if (prevMessageCountRef.current === null) {
      prevMessageCountRef.current = messageCount;
      return;
    }

    if (messageCount <= prevMessageCountRef.current) {
      prevMessageCountRef.current = messageCount;
      return;
    }

    prevMessageCountRef.current = messageCount;

    const container = scrollContainerRef.current;
    if (!container) {
      return;
    }

    const prefersReducedMotion = window.matchMedia(
      "(prefers-reduced-motion: reduce)"
    ).matches;
    container.scrollTo({
      top: container.scrollHeight,
      behavior: prefersReducedMotion ? "auto" : "smooth",
    });
  }, [messages, collapsed]);

  return (
    <div className={cn(sandboxPanelClassName(className), "h-full")}>
      <SandboxPanelHeader title="Console" icon={Terminal}>
        <div className="flex items-center gap-1">
          <span className="font-mono text-[10px] text-muted-foreground/70 tabular-nums">
            {messages.length}
          </span>
          {onClear ? (
            <Button
              variant="ghost"
              size="xs"
              className="h-6 px-1.5 text-[10px]"
              onClick={onClear}
            >
              <Trash2
                data-icon="inline-start"
                className="size-3"
                aria-hidden="true"
              />
              Clear
            </Button>
          ) : null}
          {onCollapsedChange ? (
            collapsed ? (
              <Button
                variant="ghost"
                size="icon-xs"
                className="size-6"
                onClick={() => onCollapsedChange(false)}
                aria-label="Expand console"
                aria-expanded={false}
              >
                <ChevronUp className="size-3.5" aria-hidden="true" />
              </Button>
            ) : (
              <Button
                variant="ghost"
                size="icon-xs"
                className="size-6"
                onClick={() => onCollapsedChange(true)}
                aria-label="Collapse console"
                aria-expanded={true}
              >
                <ChevronDown className="size-3.5" aria-hidden="true" />
              </Button>
            )
          ) : null}
        </div>
      </SandboxPanelHeader>

      {!collapsed ? (
        <div
          ref={scrollContainerRef}
          className="min-h-0 flex-1 overflow-y-auto overscroll-contain bg-sandbox-console-bg px-3 py-1 font-mono text-[11px] leading-5"
          role="log"
          aria-live="polite"
          aria-relevant="additions"
          translate="no"
        >
          {messages.length === 0 ? (
            <p className="py-2 text-muted-foreground/60">No output</p>
          ) : (
            messages.map((message) => (
              <div
                key={message.id}
                className="flex min-w-0 items-start gap-2 py-0.5"
              >
                <span className="shrink-0 text-muted-foreground/50 tabular-nums">
                  {formatTimestamp(message.timestamp)}
                </span>
                {message.source ? (
                  <span className={cn("shrink-0", levelTone[message.level])}>
                    [{message.source}]
                  </span>
                ) : null}
                <span
                  className={cn("min-w-0 break-all", levelTone[message.level])}
                >
                  {message.message}
                </span>
              </div>
            ))
          )}
        </div>
      ) : null}
    </div>
  );
}

export type ViewportSize = "desktop" | "tablet" | "mobile";
export type ConsoleLevel = "log" | "info" | "warn" | "error";
export type PreviewStatus = "idle" | "loading" | "ready" | "error";

export interface SandboxFile {
  id: string;
  name: string;
  path: string;
  language: "tsx" | "ts" | "css" | "json";
  content: string;
  isDirty?: boolean;
}

export interface ConsoleMessage {
  id: string;
  level: ConsoleLevel;
  message: string;
  timestamp: Date;
  source?: string;
}

export interface PackageInstallEvent {
  id: string;
  name: string;
  version: string;
  status: "pending" | "success" | "error";
  output?: string;
}

export interface RuntimeError {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}

export interface FileTreeNode {
  id: string;
  name: string;
  type: "file" | "folder";
  children?: FileTreeNode[];
  fileId?: string;
}

export interface SandboxState {
  files: SandboxFile[];
  originalContents: Record<string, string>;
  activeFileId: string;
  fileTree: FileTreeNode[];
  consoleMessages: ConsoleMessage[];
  installEvents: PackageInstallEvent[];
  runtimeError: RuntimeError | null;
  previewStatus: PreviewStatus;
  viewport: ViewportSize;
  previewSrcDoc: string;
  consoleCollapsed: boolean;
}

import { cn } from "@/lib/utils";
import type { FileTreeNode, SandboxFile } from "./types";

export function sandboxPanelClassName(className?: string): string {
  return cn(
    "flex h-full min-h-0 min-w-0 flex-col overflow-hidden bg-transparent",
    className
  );
}

export function sandboxPanelHeaderClassName(className?: string): string {
  return cn(
    "flex shrink-0 items-center justify-between gap-2 border-b border-border/60 bg-sandbox-gutter px-2.5 py-1.5",
    className
  );
}

export function sandboxShellClassName(className?: string): string {
  return cn(
    "overflow-hidden rounded-xl border border-border bg-card ring-1 ring-foreground/10",
    className
  );
}

export function getLanguageLabel(language: SandboxFile["language"]): string {
  const labels: Record<SandboxFile["language"], string> = {
    tsx: "TypeScript React",
    ts: "TypeScript",
    css: "CSS",
    json: "JSON",
  };
  return labels[language];
}

export function getLanguageBadge(language: SandboxFile["language"]): string {
  const badges: Record<SandboxFile["language"], string> = {
    tsx: "TSX",
    ts: "TS",
    css: "CSS",
    json: "JSON",
  };
  return badges[language];
}

export function formatTimestamp(date: Date): string {
  return date.toLocaleTimeString("en-US", {
    hour12: false,
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
}

export function formatCode(content: string): string {
  const lines = content.split("\n");
  let indent = 0;
  const formatted: string[] = [];

  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) {
      formatted.push("");
      continue;
    }

    if (/^[}\])]/.test(trimmed)) {
      indent = Math.max(0, indent - 1);
    }

    formatted.push(`${"  ".repeat(indent)}${trimmed}`);

    const openBrackets = (trimmed.match(/[{[(]/g) || []).length;
    const closeBrackets = (trimmed.match(/[}\])]/g) || []).length;
    indent += openBrackets - closeBrackets;
    indent = Math.max(0, indent);
  }

  return formatted.join("\n");
}

export function findFileIdInTree(
  nodes: FileTreeNode[],
  fileId: string
): string | null {
  for (const node of nodes) {
    if (node.type === "file" && node.fileId === fileId) {
      return node.id;
    }
    if (node.children) {
      const found = findFileIdInTree(node.children, fileId);
      if (found) {
        return found;
      }
    }
  }
  return null;
}

export function removeFileFromTree(
  nodes: FileTreeNode[],
  fileId: string
): FileTreeNode[] {
  return nodes
    .filter((node) => !(node.type === "file" && node.fileId === fileId))
    .map((node) =>
      node.children
        ? { ...node, children: removeFileFromTree(node.children, fileId) }
        : node
    );
}

export function addFileToTree(
  nodes: FileTreeNode[],
  file: SandboxFile
): FileTreeNode[] {
  const parts = file.path.split("/");
  if (parts.length === 1) {
    return [
      ...nodes,
      {
        id: `tree-${file.id}`,
        name: file.name,
        type: "file" as const,
        fileId: file.id,
      },
    ];
  }

  const [folderName, ...rest] = parts;
  const existingFolderIndex = nodes.findIndex(
    (node) => node.type === "folder" && node.name === folderName
  );

  if (existingFolderIndex >= 0) {
    const folder = nodes[existingFolderIndex];
    const updatedFolder: FileTreeNode = {
      ...folder,
      children: addFileToTree(folder.children ?? [], {
        ...file,
        path: rest.join("/"),
      }),
    };
    return nodes.map((node, index) =>
      index === existingFolderIndex ? updatedFolder : node
    );
  }

  return [
    ...nodes,
    {
      id: `folder-${folderName}`,
      name: folderName,
      type: "folder" as const,
      children: addFileToTree([], { ...file, path: rest.join("/") }),
    },
  ];
}

export function getViewportWidth(viewport: "desktop" | "tablet" | "mobile") {
  const widths = {
    desktop: "100%",
    tablet: "768px",
    mobile: "390px",
  } as const;
  return widths[viewport];
}

export function formatRuntimeErrorForCopy(error: {
  title: string;
  message: string;
  stack: string;
  file: string;
  line: number;
  column?: number;
}): string {
  return `${error.title}: ${error.message}
at ${error.file}:${error.line}${error.column ? `:${error.column}` : ""}

${error.stack}`;
}
